<?php
function earlyYearsAssetUrl(string $path): string { $path=trim(str_replace('\\\\','/',$path));if(preg_match('#^https?://#i',$path))return $path;$path=preg_replace('#^(?:\\.\\./)+#','',$path);return '../'.ltrim($path,'/'); }
function earlyYearsAreas(): array {
    return [
        'Communication, Language and Literacy'=>['Listening and attention','Understanding','Speaking','Reading','Writing'],
        'Mathematics Development'=>['Numbers','Shape, space and measure'],
        'Personal, Social and Emotional Development'=>['Self-confidence and self-awareness','Managing feelings and behavior','Making relationships'],
        'Knowledge and Understanding of the World'=>['People and communities','The world','Technology'],
        'Physical Development'=>['Moving and handling','Health and self-care'],
        'Expressive Arts and Design'=>['Exploring and using media and materials','Being imaginative'],
        'Islamic Religious Knowledge'=>['Listening and Attention','Understanding','Speaking'],
        'Qur’an'=>['Recitation','Memorization'],
        'Arabic'=>['Listening and Attention','Understanding','Speaking'],
    ];
}
function earlyYearsReport(mysqli $db, int $studentId, int $sessionId, int $term, string $type): ?array {
    $s=$db->prepare('SELECT s.*,c.name class_name,c.teacher_signature_path,r.report_data,r.updated_at,ac.name session_name,ets.next_term_begins,sc.school_name,sc.school_address,sc.school_phone,sc.logo_path,sc.school_stamp_path,COALESCE(hu.full_name,eys.head_name) head_name,eys.head_signature_path FROM early_years_students s JOIN early_years_classes c ON c.id=s.class_id LEFT JOIN early_years_school_settings eys ON eys.id=1 LEFT JOIN users hu ON hu.id=eys.head_user_id LEFT JOIN early_years_reports r ON r.student_id=s.id AND r.session_id=? AND r.term=? AND r.report_type=? LEFT JOIN academic_sessions ac ON ac.id=? LEFT JOIN early_years_term_settings ets ON ets.session_id=? AND ets.term=? LEFT JOIN school_config sc ON sc.id=(SELECT MAX(id) FROM school_config) WHERE s.id=?');
    $s->bind_param('iisiiii',$sessionId,$term,$type,$sessionId,$sessionId,$term,$studentId);$s->execute();$row=$s->get_result()->fetch_assoc();$s->close();
    if(!$row)return null;$row['term']=$term;$row['data']=json_decode($row['report_data']??'{}',true)?:[];return $row;
}
function earlyYearsHalfTermAreas(): array { return ['Literacy'=>'&#128214;','Numeracy'=>'&#128290;','General Studies'=>'&#11088;','Class Participation'=>'&#128101;','Arts'=>'&#127912;','IRS'=>'&#127925;','Qur�an'=>'&#128218;']; }
function earlyYearsRatingField(string $name, string $value='', bool $compact=false): string {
    $opts=$compact?['Excelling','On Track','Developing','Needs Support']:['Emerging','Expected','Exceeding'];$html='<div class="ey-ratings">';
    foreach($opts as $opt){$key=htmlspecialchars($opt,ENT_QUOTES);$checked=$value===$opt?' checked':'';$html.='<label><input type="radio" name="'.htmlspecialchars($name,ENT_QUOTES).'" value="'.$key.'"'.$checked.'> <span>'.$key.'</span></label>';}
    return $html.'</div>';
}
function earlyYearsEmoji(string $rating): string {
    $file=['Emerging'=>'emerging.svg','Expected'=>'expected.svg','Exceeding'=>'exceeding.svg'][$rating]??'';
    return $file?'<img class="ey-rating-face" src="../assets/early_years/'.$file.'" alt="'.$rating.'">':'';
}
function earlyYearsRatingDisplay(string $value): string { $options=['Excelling','On Track','Developing','Needs Support'];$html='<div class="ey-rating-display">';foreach($options as $option){$checked=$value===$option?' is-checked':'';$mark=$checked?'&#10003;':'';$html.='<span class="ey-rating-option'.$checked.'"><i aria-hidden="true">'.$mark.'</i><span>'.$option.'</span></span>'; }return $html.'</div>'; }
function earlyYearsRenderReport(array $r,string $type,bool $readOnly=false): void {
    $d=$r['data'];$half=$type==='half_term';$areas=earlyYearsAreas();
    $school=htmlspecialchars($r['school_name']?:'School');$name=htmlspecialchars($r['full_name']);$class=htmlspecialchars($r['class_name']);
    echo '<article class="ey-report '.($half?'ey-half-report':'ey-end-report').'">';
    if($half){
        echo '<header class="ey-brand"><img src="'.(!empty($r['logo_path'])?htmlspecialchars(earlyYearsAssetUrl((string)$r['logo_path']),ENT_QUOTES):'../assets/early_years/fama-crest.png').'" alt="School logo"><div><div class="ey-school">'.$school.'</div><div>'.htmlspecialchars($r['school_address']??'').' &bull; '.htmlspecialchars($r['school_phone']??'').'</div></div></header>';
        echo '<h1 class="ey-half-title">EARLY YEARS HALF-TERM PROGRESS REPORT</h1><section class="ey-meta">'.(!empty($r['passport_path'])?'<img class="ey-pupil-photo" src="'.htmlspecialchars(earlyYearsAssetUrl((string)$r['passport_path']),ENT_QUOTES).'" alt="Pupil photo">':'<div class="ey-photo-placeholder">PUPIL</div>').'<div class="ey-pupil-details"><div class="ey-detail"><small>PUPIL NAME</small><b>'.$name.'</b></div><div class="ey-detail"><small>CLASS</small><b>'.$class.'</b></div><div class="ey-detail"><small>SESSION &amp; TERM</small><b>'.htmlspecialchars($r['session_name']??'').' &bull; '.(int)$r['term'].'</b></div></div></section>';
        echo '<table class="ey-table ey-half-table"><thead><tr><th class="ey-area-col">AREA</th><th>PROGRESS</th></tr></thead><tbody>';
        foreach(earlyYearsHalfTermAreas() as $a=>$icon){$storedArea=$a==='Arts'?'Arabic':$a;$label=$icon==='&#128218;'?"Qur'an":str_replace(chr(146),"'",$a);$k='half_'.md5($storedArea);$rating=(string)($d[$k]??'');echo '<tr><td><div class="ey-area-label"><span class="ey-area-icon">'.$icon.'</span><strong>'.htmlspecialchars($label).'</strong></div></td><td>'.($readOnly?earlyYearsRatingDisplay($rating):earlyYearsRatingField('report['.$k.']',$rating,true)).'</td></tr>';}
        echo '</tbody></table>';
    }
    else {echo '<header class="ey-end-header"><img class="ey-end-kid ey-kid-left" src="../assets/early_years/end-term-girl.png" alt="Illustration of a pupil"><img class="ey-end-kid ey-kid-right" src="../assets/early_years/end-term-boy.png" alt="Illustration of a pupil"><div class="ey-school-brand">'.(!empty($r['logo_path'])?'<img class="ey-school-logo" src="'.htmlspecialchars(earlyYearsAssetUrl((string)$r['logo_path']),ENT_QUOTES).'" alt="School logo">':'<div class="ey-logo-placeholder">FAMA</div>').'<div><h1>'.htmlspecialchars($r['school_name']?:'School').'</h1><p>'.htmlspecialchars($r['school_address']??'').' &bull; '.htmlspecialchars($r['school_phone']??'').'</p></div></div><div class="ey-end-title">END OF TERM REPORT</div><div class="ey-student-banner">'.(!empty($r['passport_path'])?'<img class="ey-student-photo" src="'.htmlspecialchars(earlyYearsAssetUrl((string)$r['passport_path']),ENT_QUOTES).'" alt="Pupil photo">':'<div class="ey-student-photo ey-photo-placeholder">PUPIL</div>').'<div class="ey-student-fields"><div><small>NAME</small><b>'.$name.'</b></div><div><small>CLASS</small><b>'.$class.'</b></div><div><small>DATE</small><b>'.date('j F Y').'</b></div><div><small>NEXT TERM BEGINS</small><b>'.(!empty($r['next_term_begins'])?date('j F Y',strtotime($r['next_term_begins'])):'').'</b></div><div><small>SESSION</small><b>'.htmlspecialchars($r['session_name']??'').'</b></div><div><small>TERM</small><b>'.termLabel((int)$r['term']).'</b></div></div></div></header>'; }
    if(!$half){$pageIndex=0;foreach($areas as $area=>$items){if($area==='Expressive Arts and Design'){echo '<div class="ey-page-break"></div>'; }$areaTheme=['Communication, Language and Literacy'=>['literacy','&#128214;'],'Mathematics Development'=>['math','&#128290;'],'Personal, Social and Emotional Development'=>['social','&#127757;'],'Knowledge and Understanding of the World'=>['world','&#127758;'],'Physical Development'=>['physical','&#127939;'],'Expressive Arts and Design'=>['arts','&#127912;'],'Islamic Religious Knowledge'=>['islamic','&#128332;'],'Qur�an'=>['quran','&#128218;'],'Arabic'=>['arabic','&#128292;']];$theme=$areaTheme[$area]??['default','&#128218;'];echo '<section class="ey-area ey-area-'.$theme[0].'"><h2><span class="ey-area-heading-icon">'.$theme[1].'</span>'.htmlspecialchars(mb_strtoupper(str_replace(chr(146),"'",$area))).'</h2><table class="ey-table"><thead><tr><th>AREA OF LEARNING</th><th>Emerging<br>'.earlyYearsEmoji('Emerging').'</th><th>Expected<br>'.earlyYearsEmoji('Expected').'</th><th>Exceeding<br>'.earlyYearsEmoji('Exceeding').'</th><th>Teacher’s Comment</th></tr></thead><tbody>';foreach($items as $i=>$item){$key='a'.md5($area.'|'.$item);echo '<tr><td>'.htmlspecialchars($item).'</td>';foreach(['Emerging','Expected','Exceeding'] as $rating)echo '<td class="ey-check">'.(($d[$key]??'')===$rating?'✓':'').'</td>';if($i===0)echo '<td rowspan="'.count($items).'">'.nl2br(htmlspecialchars($d['comment_'.md5($area)]??'')).'</td>';echo '</tr>';}$qu=($area==='Qur’an');$weights=$qu?['Class Participation'=>20,'Continuous Assessment'=>20,'Examination'=>60]:(in_array($area,['Physical Development','Expressive Arts and Design'],true)?[]:['Continuous Assessment'=>20,'Class work'=>20,'Home work/Project'=>20,'Examination'=>40]);if($weights){echo '<tr class="ey-score-head">';foreach($weights as $label=>$max){$score=htmlspecialchars((string)($d['score_'.md5($area.'|'.$label)]??''));echo '<td>'.htmlspecialchars($label).' ('.$max.')'.($score!==''?'<br><b>'.$score.' / '.$max.'</b>':'').'</td>';}$sum=0;$complete=true;foreach($weights as $scoreLabel=>$scoreMax){$scoreValue=$d['score_'.md5($area.'|'.$scoreLabel)]??'';if($scoreValue===''){$complete=false;break;}$sum+=(float)$scoreValue;}$total=htmlspecialchars($complete?(string)round($sum):(string)($d['total_'.md5($area)]??''));echo '<td>TERMLY SCORE (100)'.($total!==''?'<br><b>'.$total.'</b>':'').'</td>';for($i=count($weights)+1;$i<5;$i++)echo '<td></td>';echo '</tr>'; } echo '</tbody></table></section>';}
      echo '<section class="ey-personal"><div><h2>PERSONAL QUALITIES</h2><table class="ey-table"><thead><tr><th>CRITERIA</th><th>GRADE</th></tr></thead><tbody>';foreach(['BEHAVIOUR','PUNCTUALITY','RESPECT','NEATNESS','HONESTY','POLITENESS','WILLINGNESS TO LEARN','TEAM WORK','OBEDIENCE TO CLASS/SCHOOL RULES','RELATIONSHIP WITH PEER'] as $q)echo '<tr><td>'.$q.'</td><td>'.htmlspecialchars($d['quality_'.md5($q)]??'').'</td></tr>';echo '</tbody></table></div><table class="ey-grade-key"><tr><th>GRADE</th><th>DESCRIPTION</th></tr><tr><td>NEEDS TO IMPROVE</td><td>1</td></tr><tr><td>FAIR</td><td>2</td></tr><tr><td>GOOD</td><td>3</td></tr><tr><td>VERY GOOD</td><td>4</td></tr><tr><td>EXCELLENT</td><td>5</td></tr></table></section>';}
    $teacherSignature=!empty($r['teacher_signature_path'])?'<img class="ey-signature" src="'.htmlspecialchars(earlyYearsAssetUrl((string)$r['teacher_signature_path']),ENT_QUOTES).'" alt="Class teacher signature">':'';
    $headSignature=!empty($r['head_signature_path'])?'<img class="ey-signature" src="'.htmlspecialchars(earlyYearsAssetUrl((string)$r['head_signature_path']),ENT_QUOTES).'" alt="Head of School signature">':'';
    $schoolStamp=!empty($r['school_stamp_path'])?'<img class="ey-stamp" src="'.htmlspecialchars(earlyYearsAssetUrl((string)$r['school_stamp_path']),ENT_QUOTES).'" alt="School stamp">':'';
    if($half){echo '<section class="ey-half-comments"><div class="ey-comment-card"><h2><span aria-hidden="true">&#128172;</span> TEACHER&#39;S COMMENT</h2><div class="ey-comment-text">'.nl2br(htmlspecialchars($d['teacher_comment']??'')).'</div><div class="ey-half-signature">'.$teacherSignature.'<span>Teacher&#39;s Signature</span></div></div><div class="ey-comment-card"><h2><span aria-hidden="true">&#127968;</span> HEAD OF SCHOOL&#39;S COMMENT</h2><div class="ey-comment-text">'.nl2br(htmlspecialchars($d['head_comment']??'')).'</div><div class="ey-half-signature">'.$headSignature.$schoolStamp.'<span>'.htmlspecialchars($r['head_name']?:'Head of School').'</span></div></div></section></article>';}else{echo '<section class="ey-end-comments"><div class="ey-end-comment-card"><h2>TEACHER&#39;S COMMENT</h2><div class="ey-end-comment-text">'.nl2br(htmlspecialchars($d['teacher_comment']??'')).'</div><div class="ey-end-signature">'.$teacherSignature.'<b>Teacher&#39;s Signature</b></div></div><div class="ey-end-comment-card"><h2>HEAD OF SCHOOL&#39;S COMMENT</h2><div class="ey-end-comment-text">'.nl2br(htmlspecialchars($d['head_comment']??'')).'</div><div class="ey-end-signature">'.$headSignature.'<b>'.htmlspecialchars($r['head_name']?:'Head of School').'</b></div></div></section><div class="ey-end-footer-art"><img src="../assets/early_years/end-term-books.png" alt="Books illustration"><span>Together we nurture young minds<br>for a brighter future.</span><img src="../assets/early_years/end-term-trophy.png" alt="Trophy illustration"><span class="ey-end-footer-stamp">'.$schoolStamp.'</span></div></article>'; }
}
?>
